// Shard selection for cache keys. See README for the contract with the routing table.

// FNV-1a, 32-bit, folded to a signed integer like the routing table stores it.
export function hashKey(key: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h | 0;
}

// The non-negative remainder of the hash divided by shards (Python's % semantics).
export function shardFor(key: string, shards: number): number {
  if (!Number.isInteger(shards) || shards <= 0) throw new RangeError(`shards must be a positive integer, got ${shards}`);
  return hashKey(key) % shards;
}
---
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { shardFor } from "../src/shard.ts";

const fixture = JSON.parse(readFileSync("fixtures/assignments.json", "utf8"));

test("live assignments do not move", () => {
  for (const [key, shard] of Object.entries(fixture.assignments)) {
    assert.equal(shardFor(key, fixture.shards), shard, key);
  }
});

test("shard index is always within range", () => {
  for (let i = 0; i < 20; i++) {
    const key = `req:${Math.random().toString(36).slice(2)}`;
    const s = shardFor(key, 16);
    assert.ok(s >= 0 && s < 16, `${key} -> ${s}`);
  }
});
